/**
 * The shipped catalog, loaded from generated JSON. Import the card list and
 * archetypes from the `./data` subpath so core users do not pay for them:
 *
 * ```ts
 * import { cards, sets, catalogVersion } from "@dierkens.dev/ptcg-decklist-tools/data";
 * ```
 *
 * The set index is also used by the format-window functions because membership
 * needs set order. Cards and sets are generated by `pnpm run catalog` from a
 * pinned public TCGdex dump; archetypes are snapshotted by
 * `pnpm run archetypes` from Limitless. Both builds validate their data; this
 * module only gives it the public types.
 */

import archetypesJson from "./data/archetypes.json" with { type: "json" };
import cardsJson from "./data/cards.json" with { type: "json" };
import versionJson from "./data/version.json" with { type: "json" };

import { sets } from "./sets.js";
import type { Catalog, CatalogArchetype, CatalogCard } from "./types.js";

export type { Catalog, CatalogArchetype, CatalogCard, CatalogSet } from "./types.js";
export { sets } from "./sets.js";

/** The build date of this catalog, `YYYY-MM-DD`. Store it beside a hash. */
export const catalogVersion: string = versionJson.version;

/** Every Live-addressable printing, in set and collector-number order. */
export const cards: readonly CatalogCard[] = cardsJson as readonly CatalogCard[];

/** Window-scoped Limitless archetype aliases. */
export const archetypes: readonly CatalogArchetype[] =
  archetypesJson as readonly CatalogArchetype[];

/** The whole catalog in one object, ready for `normalizeDecklist(parsed, { catalog })`. */
export const catalog: Catalog = { cards, sets, catalogVersion };
